(833837, 92979, 3102, '<td valign="top">A good idea, well carried out!</td>', 'A good idea, well carried out!', '2004-07-30 19:33:30.000000', NULL, 1),
(833838, 93082, 24511, '<td valign="top">The light and dark contrast between sky and tree is my focal point in this photo.  I feel we are in for a bit of weather.  Splendid scenery.</td>', 'The light and dark contrast between sky and tree is my focal point in this photo.  I feel we are in for a bit of weather.  Splendid scenery.', '2004-07-30 19:35:21.000000', NULL, 1),
(833843, 93448, 24511, '<td valign="top">Like a balerina I can hear an orchestra in the background.  Jonathan Livingston Seagull also has dibs on your angle giving your image flight.</td>', 'Like a balerina I can hear an orchestra in the background.  Jonathan Livingston Seagull also has dibs on your angle giving your image flight.', '2004-07-30 19:39:10.000000', NULL, 1),
(833847, 92990, 24860, '<td valign="top">I don''t like how it''s a fake rose...</td>', 'I don''t like how it''s a fake rose...', '2004-07-30 19:41:30.000000', NULL, 1),
(833860, 93607, 21714, '<td valign="top">Sharp focus and excellent DOF. I feel that you could have cropped a bit from the top and right. I am a bit uneasy with the composition. But it''s a very nice image and I love it. Well done. 9</td>', 'Sharp focus and excellent DOF. I feel that you could have cropped a bit from the top and right. I am a bit uneasy with the composition. But it''s a very nice image and I love it. Well done. 9', '2004-07-30 20:01:28.000000', NULL, 1),
(833861, 92979, 21714, '<td valign="top">Good thinking. Very creative. Nicely done.</td>', 'Good thinking. Very creative. Nicely done.', '2004-07-30 20:03:01.000000', NULL, 1),
(833864, 93903, 21714, '<td valign="top">Cool image. Nice angle and well composed. Well done.</td>', 'Cool image. Nice angle and well composed. Well done.', '2004-07-30 20:04:12.000000', NULL, 1),
(833867, 93898, 21714, '<td valign="top">Great idea, beautiful shades and well composed. I am a bit uneasy about the shiny bits on the background. I think burning them would make this an excellent image.</td>', 'Great idea, beautiful shades and well composed. I am a bit uneasy about the shiny bits on the background. I think burning them would make this an excellent image.', '2004-07-30 20:06:50.000000', NULL, 1),
(833868, 94021, 21714, '<td valign="top">Nice shot. Not too sure about where the subject is placed. Maybe a vertical would work better. Just an opinion anyway.</td>', 'Nice shot. Not too sure about where the subject is placed. Maybe a vertical would work better. Just an opinion anyway.', '2004-07-30 20:08:54.000000', NULL, 1),
(833869, 93298, 21714, '<td valign="top">Beautiful image. I like the lighting and the angle you have chosen. Well spotted. I think it''s a very well balanced image. Well done.</td>', 'Beautiful image. I like the lighting and the angle you have chosen. Well spotted. I think it''s a very well balanced image. Well done.', '2004-07-30 20:10:29.000000', NULL, 1),
