INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(834427, 92740, 19978, '<td valign="top">Elegant and beautiful. I like everything about the shot except the water dribbled on the base (or under it) of the glass, and the dirty looking table. I''m guessing it was your 38th take though, and things were just getting wet! I''m a sucker for spash shots, especially creative ones like this</td>', 'Elegant and beautiful. I like everything about the shot except the water dribbled on the base (or under it) of the glass, and the dirty looking table. I''m guessing it was your 38th take though, and things were just getting wet! I''m a sucker for spash shots, especially creative ones like this', '2004-07-31 12:25:23.000000', NULL, 1),
(834428, 93898, 19978, '<td valign="top">Very nice repetitive theme, nice dark, contrasty tones, and excellent choice of BW. I like the shot.</td>', 'Very nice repetitive theme, nice dark, contrasty tones, and excellent choice of BW. I like the shot.', '2004-07-31 12:26:41.000000', NULL, 1),
