(835032, 93841, 24486, '<td valign="top">ahhhhh.......the memories........</td>', 'ahhhhh.......the memories........', '2004-08-01 04:23:47.000000', NULL, 1),
(835033, 93930, 21576, '<td valign="top">I find this a little too dark at the bottom of the photo.</td>', 'I find this a little too dark at the bottom of the photo.', '2004-08-01 04:25:38.000000', NULL, 1),
(835035, 93874, 24486, '<td valign="top">great concept and you managed to name everyone elses ideas too :)</td>', 'great concept and you managed to name everyone elses ideas too :)', '2004-08-01 04:28:36.000000', NULL, 1),
(835037, 93491, 24486, '<td valign="top">good composition, love the title</td>', 'good composition, love the title', '2004-08-01 04:38:24.000000', NULL, 1),
(835039, 93982, 24486, '<td valign="top">Good symmetry and macro but I think your lighting source may have let you down a bit.There is a glare on some of your pencils that detracts the sharpness of your subject.</td>', 'Good symmetry and macro but I think your lighting source may have let you down a bit.There is a glare on some of your pencils that detracts the sharpness of your subject.', '2004-08-01 04:46:45.000000', NULL, 1),
(835042, 93865, 24486, '<td valign="top">Good concept but the blurred petal I find a little distracting</td>', 'Good concept but the blurred petal I find a little distracting', '2004-08-01 04:52:48.000000', NULL, 1),
(835047, 93379, 24486, '<td valign="top">When I first viewed this as a thumbnail I wasnt too sure what to think of it untill I opened it. I love the way the screen completely effects the texture of your photograph.</td>', 'When I first viewed this as a thumbnail I wasnt too sure what to think of it untill I opened it. I love the way the screen completely effects the texture of your photograph.', '2004-08-01 04:58:53.000000', NULL, 1),
(835048, 93310, 24486, '<td valign="top">Great concept and use of lighting</td>', 'Great concept and use of lighting', '2004-08-01 05:02:26.000000', NULL, 1),
(835052, 94032, 21576, '<td valign="top">I don''t really consider this an everyday object.</td>', 'I don''t really consider this an everyday object.', '2004-08-01 05:08:46.000000', NULL, 1),
(835058, 93330, 24486, '<td valign="top">Great macro shot</td>', 'Great macro shot', '2004-08-01 05:15:47.000000', NULL, 1),
