(840431, 92822, 22975, '<td valign="top">i know this photo may not follow all the standard rules of composition, but i really like it.  it''s such a simple-looking shot (but i bet it wasn''t)!  great job.  9</td>', 'i know this photo may not follow all the standard rules of composition, but i really like it.  it''s such a simple-looking shot (but i bet it wasn''t)!  great job.  9', '2004-08-03 22:05:48.000000', NULL, 1),
(840432, 93791, 12825, '<td valign="top">I would have preferred it if the depth of field was greater and more of the shot, especially the edge of the glass, was in focus.</td>', 'I would have preferred it if the depth of field was greater and more of the shot, especially the edge of the glass, was in focus.', '2004-08-03 22:06:07.000000', NULL, 1),
(840433, 93860, 12825, '<td valign="top">Heh -- good idea.</td>', 'Heh -- good idea.', '2004-08-03 22:06:43.000000', NULL, 1),
(840434, 93245, 22975, '<td valign="top">the clarity in the glass is gorgeous.  this is a very unusual capture, i really like it.  8</td>', 'the clarity in the glass is gorgeous.  this is a very unusual capture, i really like it.  8', '2004-08-03 22:06:57.000000', NULL, 1),
(840436, 93366, 22975, '<td valign="top">almost like a flower.  the arrangement is beautiful.  good job!</td>', 'almost like a flower.  the arrangement is beautiful.  good job!', '2004-08-03 22:08:09.000000', NULL, 1),
